R('linReach_adaptive 1D', ['f=@(x,u) 1-(59049/39400)*x(1)+(468559/236400)*x(1)^6-(40951/27580)*x(1)^7+0*u(1); sys=nonlinearSys(f,1,1); params.R0=zonotope(0); params.U=zonotope(0); params.tFinal=200;' ...
 'options.alg=''lin-adaptive''; try, R=reach(sys,params,options); catch ME, out=char(ME.message); return; end;' ...
 '[t,x]=ode45(@(t,x) f(x,0),[0 0.25],0); I=interval(R.timeInterval.set{1}); T=R.timeInterval.time{1};' ...
 'out=sprintf("first step [%g,%g]; Rti = [%g,%g]; x(1/4) = %g inside = %d",infimum(T),supremum(T),I.inf,I.sup,x(end),contains(R.timeInterval.set{1},x(end)));']);
R('intervalMatrix plus interval', ['M=intervalMatrix(zeros(2),zeros(2)); A=M+interval(-1,1); B=M+ones(2)*interval(-1,1); C=M+interval(-Inf,Inf); D=M+intervalMatrix(zeros(2),ones(2));' ...
 'out=sprintf("sup(M+interval(-1,1)) = %s; sup(M+ones(2)*interval(-1,1)) = %s; sup(M+interval(-Inf,Inf)) = %s; sup(M+intervalMatrix(zeros(2),ones(2))) = %s",mat2str(supremum(A.int)),mat2str(supremum(B.int)),mat2str(supremum(C.int)),mat2str(supremum(D.int)));']);
